import{_ as i,o as e,c as o,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const h=JSON.parse('{"title":"Contenido Programático: EduMática (Trayecto II)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Edumatica/Contenido_Programatico.md","filePath":"materias/Edumatica/Contenido_Programatico.md"}'),t={name:"materias/Edumatica/Contenido_Programatico.md"};function n(d,a,l,c,s,u){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="contenido-programatico-edumatica-trayecto-ii" tabindex="-1">Contenido Programático: EduMática (Trayecto II) <a class="header-anchor" href="#contenido-programatico-edumatica-trayecto-ii" aria-label="Permalink to &quot;Contenido Programático: EduMática (Trayecto II)&quot;">​</a></h1><p><strong>Unidad Curricular:</strong> EduMática <strong>Unidades Crédito:</strong> 3 <strong>Duración:</strong> 1 trimestre <strong>Código:</strong> EM213</p><hr><h2 id="🧠-saberes" tabindex="-1">🧠 SABERES <a class="header-anchor" href="#🧠-saberes" aria-label="Permalink to &quot;🧠 SABERES&quot;">​</a></h2><h3 id="unidad-1-teorias-del-aprendizaje-y-la-instruccion" tabindex="-1">Unidad 1: Teorías del aprendizaje y la instrucción <a class="header-anchor" href="#unidad-1-teorias-del-aprendizaje-y-la-instruccion" aria-label="Permalink to &quot;Unidad 1: Teorías del aprendizaje y la instrucción&quot;">​</a></h3><ul><li>Enunciar educación, instrucción y Edumática.</li><li>Identificar los tipos de teoría de la instrucción y el aprendizaje: conductivismo, cognitivismo, constructivismo.</li></ul><h3 id="unidad-2-objetivos-instruccionales" tabindex="-1">Unidad 2: Objetivos instruccionales <a class="header-anchor" href="#unidad-2-objetivos-instruccionales" aria-label="Permalink to &quot;Unidad 2: Objetivos instruccionales&quot;">​</a></h3><ul><li>Describir objetivo instruccional.</li><li>Identificar los tipos de objetivos de aprendizaje.</li><li>Escribir objetivos de aprendizaje de acuerdo al modelo de Gagné-Briggs.</li><li>Escribir objetivos de aprendizaje de acuerdo a la taxonomía de Bloom.</li></ul><h3 id="unidad-3-microclase" tabindex="-1">Unidad 3: Microclase <a class="header-anchor" href="#unidad-3-microclase" aria-label="Permalink to &quot;Unidad 3: Microclase&quot;">​</a></h3><ul><li>Describir una microclase.</li><li>Explicar los elementos de una microclase.</li><li>Ejecutar todas las técnicas de los elementos que conforman una microclase.</li></ul><h3 id="unidad-4-contenido-sinoptico-y-analitico-de-la-unidad-curricular" tabindex="-1">Unidad 4: Contenido sinóptico y analítico de la Unidad Curricular <a class="header-anchor" href="#unidad-4-contenido-sinoptico-y-analitico-de-la-unidad-curricular" aria-label="Permalink to &quot;Unidad 4: Contenido sinóptico y analítico de la Unidad Curricular&quot;">​</a></h3><ul><li>Describir unidad curricular.</li><li>Explicar la estructura de una unidad curricular y de módulo.</li><li>Mostrar técnicas para la selección de contenidos, estrategias, recursos y evaluación dentro de un programa de asignatura.</li></ul><h3 id="unidad-5-software-educativo" tabindex="-1">Unidad 5: Software Educativo <a class="header-anchor" href="#unidad-5-software-educativo" aria-label="Permalink to &quot;Unidad 5: Software Educativo&quot;">​</a></h3><ul><li>Identificar los tipos de programas computarizados educativos.</li><li>Estudiar los diferentes modelos de elaboración de software educativo.</li><li>Presentar los storyboard de una clase aplicando los eventos de Gagné.</li><li>Producir un prototipo de software educativo de un tema utilizando software de aplicación.</li></ul><hr><h2 id="📋-evaluacion" tabindex="-1">📋 EVALUACIÓN <a class="header-anchor" href="#📋-evaluacion" aria-label="Permalink to &quot;📋 EVALUACIÓN&quot;">​</a></h2><ul><li>Evaluación objetiva.</li><li>Exposición individual o en grupo de una microclase.</li><li>Entrega de informe contenido sinóptico y analítico de una unidad curricular.</li><li>Exposición individual o en grupo del desarrollo del software educativo para la unidad curricular.</li><li>Instrumento de coevaluación y auto-evaluación.</li></ul><hr><h2 id="🛠️-recursos" tabindex="-1">🛠️ RECURSOS <a class="header-anchor" href="#🛠️-recursos" aria-label="Permalink to &quot;🛠️ RECURSOS&quot;">​</a></h2><ul><li>Pizarra magnética, marcadores.</li><li><strong>Material Educativo Computarizado:</strong> Material Instructivo, Software.</li><li>Computador, Proyector Multimedia, Plataforma Tecnológica.</li><li>Aula de encuentros, aula taller, laboratorios.</li></ul>',20)])])}const p=i(t,[["render",n]]);export{h as __pageData,p as default};
